import{_ as t,o as n,c as i,a9 as o}from"./chunks/framework.AY-u9rel.js";const p=JSON.parse(`{"title":"Contribution Guide","description":"How to propose a Feluqa contribution and find the guides for working with the Feluqa team.","frontmatter":{"requestedLanguage":"fr","contentLanguage":"en","languageFallbackNotice":"Cette page n’est pas disponible en Français. La version en anglais est affichée.","sidebarTitle":"Contributing","icon":"git-pull-request","title":"Contribution Guide","description":"How to propose a Feluqa contribution and find the guides for working with the Feluqa team.","summary":"Explains how to propose a contribution through Feluqa's GitHub page, discuss scope and terms with maintainers, and find the core contribution guidance and AI-agent skills.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":3,"status":"Exploring","tags":["feluqa","contribution","development","agents"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"},"prev":{"text":"Components","link":"/fr/prologue/components"},"next":{"text":"License","link":"/fr/prologue/licence"}},"headers":[],"relativePath":"fr/prologue/contribution-guide.md","filePath":"fr/prologue/contribution-guide.md"}`),a={name:"fr/prologue/contribution-guide.md"};function r(s,e,l,u,c,d){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="contribution-guide" tabindex="-1">Contribution Guide <a class="header-anchor" href="#contribution-guide" aria-label="Permalink to &quot;Contribution Guide&quot;">​</a></h1><p>We welcome contributions and aim to collaborate directly with contributors. Start by reaching out through <a href="https://github.com/feluqa/" target="_blank" rel="noreferrer">Feluqa on GitHub</a>, describe what you would like to improve, and request the access needed for the work. A public issues and discussions space for these requests is planned and will be linked from the GitHub page when ready.</p><p>Maintainers will work with you on scope and implementation, arrange access, and agree the terms for your contribution before incorporating it. Read <a href="/fr/prologue/licence">Build with Feluqa</a> for the licensing model and contribution terms. For source-level engineering guidance, see <a href="/fr/internals/get-started/overview/internals-overview">Core Contribution</a>.</p><p>Organisations interested in building a Product or contributing to Feluqa&#39;s developer tools (SDK) with their own engineering team can also use the contact path above. The licence page explains the client-product and internal-team options.</p><h2 id="working-agreements" tabindex="-1">Working agreements <a class="header-anchor" href="#working-agreements" aria-label="Permalink to &quot;Working agreements&quot;">​</a></h2><ul><li>Follow the contribution instructions, Rust coding standard, and documentation voice and tone that apply to the work.</li><li>Keep changes focused on a useful behavior or clear documentation outcome.</li><li>For Rust changes, use the documented facade APIs and lint policy, handle errors explicitly, and include coverage appropriate to the behavior changed.</li><li>For documentation changes, check links, terminology, and whether claims match current implementation and product direction.</li><li>Run the checks appropriate to the change and report what you ran and any existing failures.</li></ul><p>The source-level engineering rules are collected in the <a href="/fr/internals/get-started/overview/internals-overview">Core Contribution</a> section. These published guides provide contributors with an entry point to that work.</p><h2 id="skills-for-ai-agents" tabindex="-1">Skills for AI agents <a class="header-anchor" href="#skills-for-ai-agents" aria-label="Permalink to &quot;Skills for AI agents&quot;">​</a></h2><p>Feluqa also maintains <a href="/fr/agents/get-started/overview/agents-overview"><code>x-agents</code></a>, a collection of skills for AI agents working with Feluqa. Skills provide reusable, task-specific workflows. They supplement the relevant contribution and technical guides; they do not replace the applicable engineering rules.</p><p>Human contributors can read the skills as useful references, but do not need to install or use agent-specific tooling to contribute.</p>',10)])])}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
